import ast
import pathlib
py_paths = ['scripts/witness_asset_catalog.py', 'src/viz/embed_display_boundary.py', 'tests/test_assets_registry.py', 'tests/test_implied_lab_embed_display_boundary.py', 'tests/test_lab_asset_selection.py']
other_paths = ['config/assets.yaml', 'config/assets_tier1_manifest.yaml']
for path in py_paths:
    ast.parse(pathlib.Path(path).read_text(encoding='utf-8'))
for path in other_paths:
    text = pathlib.Path(path).read_text(encoding='utf-8')
    if not text.strip():
        raise SystemExit('empty patched file: ' + path)
